template.css:
.qdrant-similarity-panel {
  background: #1a1a2e;
  border: 2px solid #ff88ff;
  border-radius: 12px;
  padding: 15px;
  height: 100%;
  display: flex;
  flex-direction: column;
}
.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
  padding-bottom: 12px;
  border-bottom: 2px solid #ff88ff;
}
.panel-title {
  color: #ff88ff;
  font-size: 1.1em;
  font-weight: bold;
}
.panel-badge {
  padding: 4px 10px;
  background: linear-gradient(135deg, #ff88ff, #ff44ff);
  color: #000;
  font-size: 0.75em;
  font-weight: bold;
  border-radius: 4px;
  text-transform: uppercase;
}
.search-controls {
  display: flex;
  gap: 8px;
  margin-bottom: 15px;
}
.search-input {
  flex: 1;
  padding: 10px;
  background: #0a0a0a;
  border: 2px solid #333;
  border-radius: 6px;
  color: #00ff88;
  font-family: inherit;
  font-size: 0.9em;
}
.search-input:focus {
  outline: none;
  border-color: #ff88ff;
}
.search-btn {
  padding: 10px 15px;
  background: linear-gradient(135deg, #ff88ff, #ff44ff);
  border: none;
  border-radius: 6px;
  color: #000;
  font-size: 1.2em;
  cursor: pointer;
  transition: all 0.2s;
}
.search-btn:hover {
  transform: scale(1.05);
  box-shadow: 0 0 15px rgba(255, 136, 255, 0.5);
}
.results-container {
  flex: 1;
  overflow-y: auto;
}
.no-results {
  text-align: center;
  color: #666;
  padding: 30px 15px;
  font-size: 0.9em;
}
.similarity-result {
  background: #0a0a0a;
  border: 1px solid #333;
  border-left: 3px solid #ff88ff;
  border-radius: 6px;
  padding: 12px;
  margin-bottom: 10px;
  cursor: pointer;
  transition: all 0.2s;
}
.similarity-result:hover {
  border-left-color: #00ff88;
  background: rgba(255, 136, 255, 0.05);
  transform: translateX(5px);
}
.result-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.result-patient {
  color: #00ff88;
  font-weight: bold;
  font-size: 0.95em;
}
.result-score {
  padding: 4px 8px;
  background: rgba(255, 136, 255, 0.2);
  border: 1px solid #ff88ff;
  border-radius: 4px;
  color: #ff88ff;
  font-size: 0.8em;
  font-weight: bold;
}
.result-info {
  font-size: 0.85em;
  color: #888;
  margin-top: 5px;
}
.result-modality {
  display: inline-block;
  padding: 2px 6px;
  background: rgba(0, 204, 255, 0.2);
  border: 1px solid #00ccff;
  border-radius: 3px;
  color: #00ccff;
  font-size: 0.75em;
  margin-right: 8px;
}

template.js:
function initQdrantSimilarityPanel(element, config) {
  const searchInput = element.querySelector('#' + config.id + '-search');
  const searchBtn = element.querySelector('#' + config.id + '-btn');
  const resultsContainer = element.querySelector('#' + config.id + '-results');

  function performSearch() {
    const query = searchInput.value;
    if (!query) return;

    // In production, call Qdrant API
    console.log('Searching Qdrant for:', query);

    // Show loading state
    resultsContainer.innerHTML = '<div class="no-results">Searching Qdrant vector database...</div>';

    // Simulate API call
    setTimeout(() => {
      // Mock results
      displayResults(mockResults());
    }, 1000);
  }

  function displayResults(results) {
    if (!results || results.length === 0) {
      resultsContainer.innerHTML = '<div class="no-results">No similar cases found</div>';
      return;
    }

    resultsContainer.innerHTML = '';
    results.forEach(result => {
      const resultEl = createResultElement(result);
      resultsContainer.appendChild(resultEl);
    });
  }

  function createResultElement(result) {
    const div = document.createElement('div');
    div.className = 'similarity-result';
    div.innerHTML = `
      <div class="result-header">
        <div class="result-patient">${result.patientName}</div>
        <div class="result-score">${(result.score * 100).toFixed(1)}%</div>
      </div>
      <div class="result-info">
        <span class="result-modality">${result.modality}</span>
        ${result.description}
      </div>
      <div class="result-info" style="margin-top: 5px; color: #666;">
        ${result.date} • ${result.diagnosis || 'No diagnosis'}
      </div>
    `;

    div.addEventListener('click', () => {
      if (config.onResultClick) {
        config.onResultClick(result);
      }
    });

    return div;
  }

  function mockResults() {
    return [
      {
        patientName: 'SMITH, Jane',
        score: 0.94,
        modality: 'CT',
        description: 'Brain CT - Similar pattern',
        date: '2025-10-15',
        diagnosis: "Alzheimer's - Early stage"
      },
      {
        patientName: 'DOE, John',
        score: 0.87,
        modality: 'MR',
        description: 'Brain MRI - Hippocampal atrophy',
        date: '2025-09-22',
        diagnosis: "Alzheimer's - Moderate"
      },
      {
        patientName: 'JOHNSON, Mary',
        score: 0.82,
        modality: 'XR',
        description: 'Brain X-Ray - AlF accumulation',
        date: '2025-11-01',
        diagnosis: 'High AlF risk'
      }
    ];
  }

  searchBtn.addEventListener('click', performSearch);
  searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') performSearch();
  });

  return { displayResults };
}
